//! Exact ordinary names survive native owner transfer.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=mount></div><span name='A�z'></span></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn passive_name_materialization_import_preserves_exact_names_and_independent_owners(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('div');source.setAttribute('name','A\ud800z');source.textContent='copied';owner.body.appendChild(source);var a=source.getAttributeNode('name'),old=owner.getElementsByName('A\ud800z'),live=document.getElementsByName('A\ud800z'),copy=document.importNode(source,true),b=copy.getAttributeNode('name');if(copy===source||copy.ownerDocument!==document||copy.getAttribute('name')!==a.value||copy.textContent!=='copied'||a===b||b.ownerDocument!==document||b.ownerElement!==copy||a.ownerDocument!==owner||a.ownerElement!==source||source.parentNode!==owner.body||live.length||old[0]!==source)throw 'independent import';document.getElementById('mount').appendChild(copy);if(live.length!==1||live[0]!==copy||document.getElementsByName('A�z').length!==1||document.getElementsByTagName('div').namedItem(a.value)!==copy)throw 'exact imported filter';b.value='B\udfffz';if(live.length||old[0]!==source||a.value!=='A\ud800z'||document.getElementsByName(b.value)[0]!==copy)throw 'independent values';
"#);}
#[test]
fn passive_name_materialization_parked_promotion_preserves_attr_identity_and_live_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var t=document.createElement('template');t.innerHTML='<span name=seed>promoted</span>';var source=t.content.firstChild,owner=source.ownerDocument,a=source.getAttributeNode('name'),mount=document.getElementById('mount'),live=document.getElementsByName('A\ud800z'),watch=new MutationObserver(function(){});a.value='A\ud800z';watch.observe(mount,{childList:true});mount.appendChild(t.content);if(source.ownerDocument!==document||source.getAttributeNode('name')!==a||a.ownerDocument!==document||a.ownerElement!==source||live.length!==1||live[0]!==source||document.getElementsByName('A�z')[0]===source||t.content.childNodes.length)throw 'promoted identities';var records=watch.takeRecords();if(records.length!==1||records[0].addedNodes[0]!==source||records[0].target!==mount)throw 'promotion record';a.value='B\udfffz';if(live.length||document.getElementsByName(a.value)[0]!==source)throw 'live replacement';
"#);}
#[test]
fn passive_name_materialization_template_import_clones_raw_names_before_promotion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var t=document.createElement('template');t.innerHTML='<div><span name=seed>held</span></div>';var original=t.content.firstChild.firstChild;original.setAttribute('name','B\udfffz');var c=document.importNode(t,true),copy=c.content.firstChild.firstChild,a=copy.getAttributeNode('name'),live=document.getElementsByName(a.value);if(copy===original||copy.ownerDocument===document||copy.isConnected||copy.getAttribute('name')!==original.getAttribute('name')||live.length)throw 'inert clone';document.getElementById('mount').appendChild(c.content);if(copy.ownerDocument!==document||a.ownerDocument!==document||copy.getAttributeNode('name')!==a||live[0]!==copy||original.ownerDocument===document||t.content.firstChild.firstChild!==original)throw 'promoted clone';copy.removeAttribute('name');if(live.length||original.getAttribute('name')!=='B\udfffz'||a.ownerElement!==null||a.value!=='B\udfffz')throw 'independent removal';
"#);}

#[test]
fn passive_name_materialization_import_and_promotion_resource_refusal_is_atomic_and_recovers(){
 for promote in [false,true]{let(mut d,mut forms,mut page)=fixture();run(&mut d,&mut forms,&mut page,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('div');source.setAttribute('name','long A\ud800z');source.textContent='held';owner.body.appendChild(source);var t=document.createElement('template');t.innerHTML='<span name=seed>held</span>';var parked=t.content.firstChild;parked.setAttribute('name','long B\udfffz');var a=source.getAttributeNode('name'),b=parked.getAttributeNode('name'),oldOwner=parked.ownerDocument,mount=document.getElementById('mount'),watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});"#);page.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(page.state.retained,page.state.dom_commits,page.state.attributes.len());let limit=page.state.retained_limit;
  for mode in 0..3{page.begin_job();match mode{0=>page.state.host_work=0,1=>page.state.copy_work=0,_=>page.state.retained_limit=0};let source=if promote{"mount.appendChild(t.content);"}else{"document.importNode(source,true);"};let error=page.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut forms,state:&mut page.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((page.state.retained,page.state.dom_commits,page.state.attributes.len()),state);page.state.retained_limit=limit;}
  page.begin_job();run(&mut d,&mut forms,&mut page,r#"if(source.parentNode!==owner.body||a.ownerDocument!==owner||a.value!=='long A\ud800z'||parked.parentNode!==t.content||parked.ownerDocument!==oldOwner||b.ownerDocument!==oldOwner||b.value!=='long B\udfffz'||watch.takeRecords().length||mount.childNodes.length)throw 'refusal publication';var copy=document.importNode(source,true);mount.appendChild(copy);mount.appendChild(t.content);if(document.getElementsByName(a.value)[0]!==copy||document.getElementsByName(b.value)[0]!==parked||parked.getAttributeNode('name')!==b||b.ownerDocument!==document)throw 'fresh recovery';"#);
 }
}
#[test]
fn passive_name_materialization_protected_names_keep_import_and_promotion_guards(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),input=owner.createElement('input'),slot=owner.createElement('slot'),style=owner.createElement('style'),foreign=owner.createElementNS('http://www.w3.org/2000/svg','g'),qualified=owner.createElement('div');input.setAttribute('name','A\ud800z');slot.setAttribute('name','A\ud800z');style.setAttribute('name','A\ud800z');foreign.setAttribute('name','A\ud800z');qualified.setAttributeNS('urn:attr','name','A\ud800z');var t=document.createElement('template');t.innerHTML='<slot name=seed></slot>';var parked=t.content.firstChild,a=parked.getAttributeNode('name'),oldOwner=parked.ownerDocument;a.value='A\ud800z';var mount=document.getElementById('mount');"#);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());
 for source in ["document.importNode(slot,true);","document.importNode(style,true);","document.importNode(foreign,true);","document.importNode(qualified,true);","mount.appendChild(t.content);"]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{source}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}
 run(&mut d,&mut f,&mut p,r#"if(input.ownerDocument!==owner||input.getAttribute('name')!=='A\ud800z'||parked.parentNode!==t.content||a.ownerDocument!==oldOwner||a.ownerElement!==parked||mount.childNodes.length)throw 'protected publication';var good=owner.createElement('span');good.setAttribute('name','B\udfffz');var c=document.importNode(good,true);mount.appendChild(c);if(document.getElementsByName('B\udfffz')[0]!==c)throw 'protected recovery';"#);
 p.begin_job();run(&mut d,&mut f,&mut p,r#"var copiedInput=document.importNode(input,true),sourceName=input.getAttributeNode('name'),copiedName=copiedInput.getAttributeNode('name');if(copiedInput===input||copiedInput.ownerDocument!==document||copiedInput.parentNode!==null||copiedInput.name!=='A\ud800z'||copiedName.value!==input.name||copiedName===sourceName||copiedName.ownerElement!==copiedInput||copiedName.ownerDocument!==document||input.ownerDocument!==owner||sourceName.ownerElement!==input||sourceName.ownerDocument!==owner)throw 'supported raw input import';copiedInput.name='Changed\udfff';if(input.name!=='A\ud800z'||copiedName.value!=='Changed\udfff'||copiedInput.name!==copiedName.value)throw 'independent imported name';"#);

}
#[test]
fn passive_name_materialization_shared_policy_requires_exact_html_ordinary_name(){
 let attr=crate::html::Attribute{name:crate::html::AttributeName::unqualified("name".into()),value:DomString::from_units(&[65,0xd800,122],4096).unwrap()};
 for tag in ["div","span","p","a","section","table","td","x-original","input","textarea","select","button","form","output","fieldset"]{assert!(script_attr::materializable_value(&attr,crate::html::Namespace::Html,tag),"{tag}");}
 for tag in ["option","slot","iframe","img","script","style","link","meta"]{assert!(!script_attr::materializable_value(&attr,crate::html::Namespace::Html,tag),"{tag}");}
 for ns in [crate::html::Namespace::Svg,crate::html::Namespace::Other]{assert!(!script_attr::materializable_value(&attr,ns,"div"));}
}
